23	/** Loose sanity check for a literal IPv4/IPv6 address (no CIDR / ranges). */
24	function isPlainIp(s: string): boolean {
25	  return /^\d{1,3}(\.\d{1,3}){3}$/.test(s) || (s.includes(":") && /^[0-9a-fA-F:]+$/.test(s));
26	}
27	
28	/**
29	 * IP allow-list gate for /admin. `allowed_admin_ips` is a comma-separated list of
30	 * literal IPs; empty = no restriction. Fails OPEN (allows) when the list has no
31	 * parseable entries or the requester IP can't be determined, so a bad value can
32	 * never lock every admin out — only an exact match is ever enforced.
33	 * Returns true when access should be REFUSED.
34	 */
35	async function adminIpBlocked(): Promise<boolean> {
36	  const raw = await getSetting("allowed_admin_ips", "");
37	  const entries = raw.split(",").map((s) => s.trim()).filter(Boolean);
38	  if (entries.length === 0) return false; // no restriction configured
39	  const valid = entries.filter(isPlainIp);
40	  if (valid.length === 0) {
41	    console.warn("[admin-ip] allowed_admin_ips is set but has no valid IPs; failing open:", raw);
42	    return false; // malformed -> fail open
43	  }
44	  const hdrs = await headers();
45	  // Trust nginx's X-Real-IP ($remote_addr), which the client cannot forge. Fall
46	  // back to the LAST X-Forwarded-For hop (the one our proxy appended), never the
47	  // client-supplied leftmost entry.
48	  const xff = (hdrs.get("x-forwarded-for") ?? "").split(",").map((s) => s.trim()).filter(Boolean);
49	  const ip = hdrs.get("x-real-ip")?.trim() || xff[xff.length - 1] || "";
50	  if (!ip) {
51	    console.warn("[admin-ip] could not determine requester IP; failing open");
52	    return false;
53	  }
54	  return !valid.includes(ip);
55	}
