119	export default async function AdminLayout({ children }: { children: React.ReactNode }) {
120	  // Wrong host (e.g. public nxeon.cloud) → 404, so /admin isn't reachable there.
121	  if (await adminHostBlocked()) notFound();
122	
123	  const user = await realUser();
124	  if (!user) redirect("/login");
125	  if (!isStaff(user.role)) redirect("/dashboard");
126	  const imp = await impersonating();
127	  if (imp) redirect("/dashboard"); // exit impersonation before using admin tools
128	
129	  // IP allow-list: refuse admin access from an IP that isn't explicitly allowed.
130	  if (await adminIpBlocked()) {
131	    return (
132	      <main
133	        style={{
134	          minHeight: "100vh",
135	          display: "flex",
136	          flexDirection: "column",
137	          alignItems: "center",
138	          justifyContent: "center",
139	          gap: "0.75rem",
140	          padding: "2rem",
141	          textAlign: "center",
142	        }}
143	      >
144	        <h1 style={{ fontSize: "1.5rem", fontWeight: 600 }}>Access restricted</h1>
145	        <p style={{ maxWidth: "32rem", opacity: 0.8 }}>
146	          The admin console isn&apos;t available from your current network.
147	        </p>
148	      </main>
149	    );
150	  }
151	
152	  // Staff 2FA enforcement: when enabled, staff without TOTP must set it up before
153	  // using admin tools. Redirect (don't hard-fail) to their security settings so
154	  // they can enroll, then come back.
155	  if ((await getSettingBool("enforce_staff_2fa", false)) && !user.totpEnabled) {
156	    redirect("/dashboard/settings?require2fa=1");
157	  }
158	
159	  // Hide nav items this role can't access; drop sections that end up empty.
160	  const visibleNav: NavSection[] = nav
161	    .map((section) => ({
162	      ...section,
163	      items: section.items.filter((item) => canAccessHref(user.role, item.href)),
164	    }))
165	    .filter((section) => section.items.length > 0);
166	
167	  const notifications = await db.notification.findMany({
168	    where: { userId: user.id },
169	    orderBy: { createdAt: "desc" },
170	    take: 15,
171	  });
172	
173	  // Attention-count badges for the sidebar. Each count fails soft (→ 0) so a
174	  // missing model/table can never break the admin layout.
175	  const soft = (p: Promise<number>) => p.catch(() => 0);
176	  const [chatUnread, ticketsAwaiting, abuseOpen, feedbackNew] = await Promise.all([
177	    // Live chat: conversations flagged unread for agents (same "needs a reply"
178	    // signal the chat inbox sorts/counts by — ChatConversation.unreadForAgent).
179	    soft(db.chatConversation.count({ where: { unreadForAgent: true } })),
180	    // Support desk: tickets awaiting a staff reply (open + customer replies),
181	    // matching the "Awaiting staff" stat on /admin/support.
182	    soft(db.ticket.count({ where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] } } })),
183	    // Abuse queue: alerts still OPEN.
184	    soft(db.abuseAlert.count({ where: { status: "OPEN" } })),
185	    // Feedback: new (untriaged) reports.
186	    soft(db.feedback.count({ where: { status: "NEW" } })),
187	  ]);
188	
189	  const badges: Record<string, number> = {
190	    "/admin/chat": chatUnread,
191	    "/admin/support": ticketsAwaiting,
192	    "/admin/abuse": abuseOpen,
193	    "/admin/feedback": feedbackNew,
194	  };
195	  const navWithBadges: NavSection[] = visibleNav.map((section) => ({
196	    ...section,
197	    items: section.items.map((item) =>
198	      badges[item.href] > 0 ? { ...item, badge: badges[item.href] } : item
199	    ),
200	  }));
201	
202	  return (
203	    <Shell
204	      nav={navWithBadges}
205	      tag="ops"
206	      user={{ name: user.name, email: user.email, role: user.role, balanceCents: user.balanceCents }}
207	      notifications={notifications.map((n) => ({
208	        id: n.id,
209	        title: n.title,
210	        body: n.body,
211	        href: n.href,
212	        readAt: n.readAt ? n.readAt.toISOString() : null,
213	        createdAt: n.createdAt.toISOString(),
214	      }))}
215	    >
216	      {children}
217	    </Shell>
218	  );
219	}
