/**
 * Grouped structure for the admin ops portal.
 *
 * The sidebar shows one TOP-LEVEL entry per group (its `href` points at the
 * group's first member). Each grouped page renders a horizontal sub-tab bar for
 * its siblings via <AdminSubTabs /> (see components/admin/SubTabs.tsx), so the
 * ~40 admin routes stay one click apart without cluttering the sidebar.
 *
 * This module is intentionally free of any server-only imports so it can be
 * consumed by both the server admin layout (for badge roll-up) and the client
 * sub-tab bar.
 */

export type SubTabItem = { label: string; href: string };

export type AdminGroup = {
  /** Stable key for the group. */
  key: string;
  /** Sidebar label. */
  label: string;
  /** Shell icon name (see components/portal/Shell.tsx icons map). */
  icon: string;
  /** Members, in display order. items[0].href is the group's landing page. */
  items: SubTabItem[];
};

export const ADMIN_GROUPS: AdminGroup[] = [
  {
    key: "insights",
    label: "Insights",
    icon: "chart",
    items: [
      { label: "Overview", href: "/admin" },
      { label: "Analytics", href: "/admin/analytics" },
      { label: "Visitors", href: "/admin/visitors" },
    ],
  },
  {
    key: "customers",
    label: "Customers",
    icon: "users",
    items: [
      { label: "Clients", href: "/admin/users" },
      { label: "Support desk", href: "/admin/support" },
      { label: "Live chat", href: "/admin/chat" },
      { label: "Feedback", href: "/admin/feedback" },
      { label: "Organizations", href: "/admin/orgs" },
    ],
  },
  {
    key: "fleet",
    label: "Fleet",
    icon: "server",
    items: [
      { label: "Servers", href: "/admin/servers" },
      { label: "Nodes", href: "/admin/nodes" },
      { label: "IP pool", href: "/admin/ips" },
      { label: "Provisioning", href: "/admin/provisioning" },
      { label: "Jobs", href: "/admin/jobs" },
      { label: "Monitoring", href: "/admin/monitoring" },
      { label: "Abuse queue", href: "/admin/abuse" },
      { label: "Infrastructure", href: "/admin/infrastructure" },
    ],
  },
  {
    key: "revenue",
    label: "Revenue",
    icon: "dollar",
    items: [
      { label: "Subscriptions", href: "/admin/subscriptions" },
      { label: "Billing", href: "/admin/billing" },
      { label: "Invoices", href: "/admin/invoices" },
      { label: "Plans", href: "/admin/plans" },
      { label: "Game plans", href: "/admin/game-plans" },
      { label: "Coupons", href: "/admin/coupons" },
      { label: "Gift codes", href: "/admin/gift-codes" },
      { label: "Email plans", href: "/admin/email-plans" },
      { label: "Add-on products", href: "/admin/products" },
      { label: "Affiliate", href: "/admin/affiliate" },
    ],
  },
  {
    key: "platform",
    label: "Platform",
    icon: "globe",
    items: [
      { label: "Domains", href: "/admin/domains" },
      { label: "Grant VPS", href: "/admin/grant" },
      { label: "Blog", href: "/admin/blog" },
      { label: "Game servers", href: "/admin/games" },
      { label: "Logs", href: "/admin/logs" },
      { label: "Mail deliverability", href: "/admin/mail" },
      { label: "Newsletter", href: "/admin/newsletter" },
      { label: "Testimonials", href: "/admin/testimonials" },
      { label: "Automation", href: "/admin/automation" },
      { label: "Staff", href: "/admin/staff" },
      { label: "Audit", href: "/admin/audit" },
    ],
  },
  {
    key: "system",
    label: "System",
    icon: "cog",
    items: [
      { label: "Settings", href: "/admin/settings" },
      { label: "Email templates", href: "/admin/email-templates" },
      { label: "Docs", href: "/admin/docs" },
      { label: "Improvements", href: "/admin/improvements" },
    ],
  },
];

/**
 * Resolve which group a given admin pathname belongs to, by longest matching
 * member href. Detail routes (e.g. /admin/users/123) resolve to their group via
 * the prefix match. The bare "/admin" only ever matches the Insights overview
 * so it never swallows deeper routes.
 */
export function groupForPath(pathname: string): AdminGroup | null {
  let best: { group: AdminGroup; len: number } | null = null;
  for (const group of ADMIN_GROUPS) {
    for (const item of group.items) {
      const matches =
        pathname === item.href ||
        (item.href !== "/admin" && pathname.startsWith(item.href + "/"));
      if (matches && (!best || item.href.length > best.len)) {
        best = { group, len: item.href.length };
      }
    }
  }
  return best?.group ?? null;
}

"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { ADMIN_GROUPS, groupForPath, type SubTabItem } from "@/lib/admin-groups";

/**
 * Horizontal pill/tab bar for an admin group's members. Highlights the active
 * item via usePathname. The bare "/admin" overview only lights up on an exact
 * match; every other tab also lights up for its detail routes (prefix match).
 */
export function SubTabs({ items }: { items: SubTabItem[] }) {
  const pathname = usePathname();
  if (items.length < 2) return null;

  return (
    <nav className="mb-6 flex flex-wrap items-center gap-1.5 border-b border-white/[0.06] pb-3">
      {items.map((item) => {
        const active =
          item.href === pathname ||
          (item.href !== "/admin" && pathname.startsWith(item.href + "/"));
        return (
          <Link
            key={item.href}
            href={item.href}
            className={`rounded-full px-3.5 py-1.5 text-[13px] font-medium transition-colors ${
              active
                ? "bg-brand-500/15 text-brand-200 ring-1 ring-inset ring-brand-500/40"
                : "text-slate-400 hover:bg-white/[0.05] hover:text-slate-200"
            }`}
          >
            {item.label}
          </Link>
        );
      })}
    </nav>
  );
}

/**
 * Auto-resolving sub-tab bar. Reads the current path, finds its admin group and
 * renders that group's <SubTabs />. Dropped once into the admin layout so every
 * grouped page gets its sub-navigation without per-page wiring. Renders nothing
 * for paths outside any group.
 */
export function AdminSubTabs() {
  const pathname = usePathname();
  const group = groupForPath(pathname);
  if (!group) return null;
  // Suppress the "Insights" bar on the dense overview dashboard where it would
  // sit oddly above the stat grid; every other group keeps its bar.
  if (group.key === "insights" && pathname === "/admin") {
    return <SubTabs items={ADMIN_GROUPS[0].items} />;
  }
  return <SubTabs items={group.items} />;
}

