/**
 * Tiny, dependency-free, safe Markdown → HTML renderer.
 *
 * Deliberately minimal: it supports the subset used by our internal docs
 * (headings, bold/italic, inline code, fenced/indented code blocks, unordered &
 * ordered lists, blockquotes, links, horizontal rules, paragraphs). It is NOT a
 * general CommonMark implementation.
 *
 * Safety: ALL raw text is HTML-escaped before any markup is emitted, so the
 * rendered document can never inject markup or scripts from the source file.
 * Link targets are whitelisted to http(s)/mailto/relative/anchor URLs; anything
 * else (e.g. javascript:) is dropped and rendered as plain text.
 */

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function safeUrl(url: string): string | null {
  const u = url.trim();
  if (/^(https?:\/\/|mailto:)/i.test(u)) return u;
  if (u.startsWith("/") || u.startsWith("#")) return u;
  return null;
}

/** Inline formatting on a single (already block-stripped) line of raw text. */
function renderInline(raw: string): string {
  // Pull out inline code first so ** / * / [] inside code stay literal.
  const codes: string[] = [];
  let text = raw.replace(/`([^`]+)`/g, (_m, code) => {
    codes.push(`<code class="rounded bg-white/[0.07] px-1.5 py-0.5 text-[0.85em] text-brand-200">${escapeHtml(code)}</code>`);
    return `�${codes.length - 1}�`;
  });

  text = escapeHtml(text);

  // Links: [label](url) — escapeHtml already ran, so brackets/parens are intact.
  text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (m, label, url) => {
    const href = safeUrl(url);
    if (!href) return label;
    return `<a href="${escapeHtml(href)}" class="text-brand-300 underline decoration-brand-500/40 underline-offset-2 hover:text-brand-200" target="_blank" rel="noreferrer">${label}</a>`;
  });

  text = text.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
  text = text.replace(/(^|[^*])\*([^*]+)\*/g, "$1<em>$2</em>");
  text = text.replace(/(^|[^_])_([^_]+)_/g, "$1<em>$2</em>");

  // Restore code placeholders.
  text = text.replace(/�(\d+)�/g, (_m, i) => codes[Number(i)]);
  return text;
}

/** Render Markdown source to a sanitized HTML string. */
export function renderMarkdown(src: string): string {
  const lines = src.replace(/\r\n/g, "\n").split("\n");
  const out: string[] = [];
  let i = 0;

  const flushList = (items: string[], ordered: boolean) => {
    if (items.length === 0) return;
    const tag = ordered ? "ol" : "ul";
    const cls = ordered ? "ml-5 list-decimal space-y-1" : "ml-5 list-disc space-y-1";
    out.push(`<${tag} class="${cls} text-slate-300">${items.map((it) => `<li>${renderInline(it)}</li>`).join("")}</${tag}>`);
  };

  while (i < lines.length) {
    const line = lines[i];

    // Fenced code block.
    const fence = line.match(/^```(.*)$/);
    if (fence) {
      const body: string[] = [];
      i++;
      while (i < lines.length && !/^```/.test(lines[i])) {
        body.push(lines[i]);
        i++;
      }
      i++; // consume closing fence
      out.push(
        `<pre class="overflow-x-auto rounded-xl border border-white/[0.07] bg-navy-950/70 p-4 text-[13px] leading-relaxed text-slate-200"><code>${escapeHtml(body.join("\n"))}</code></pre>`
      );
      continue;
    }

    // Blank line.
    if (line.trim() === "") {
      i++;
      continue;
    }

    // Horizontal rule.
    if (/^(-{3,}|\*{3,}|_{3,})$/.test(line.trim())) {
      out.push('<hr class="my-6 border-white/[0.08]" />');
      i++;
      continue;
    }

    // Heading.
    const h = line.match(/^(#{1,6})\s+(.*)$/);
    if (h) {
      const level = h[1].length;
      const sizes: Record<number, string> = {
        1: "mt-2 text-2xl font-bold tracking-tight text-white",
        2: "mt-8 text-xl font-bold tracking-tight text-white",
        3: "mt-6 text-lg font-semibold text-white",
        4: "mt-5 text-base font-semibold text-slate-100",
        5: "mt-4 text-sm font-semibold text-slate-200",
        6: "mt-4 text-sm font-semibold text-slate-300",
      };
      out.push(`<h${level} class="${sizes[level] ?? sizes[6]}">${renderInline(h[2])}</h${level}>`);
      i++;
      continue;
    }

    // Blockquote.
    if (/^>\s?/.test(line)) {
      const body: string[] = [];
      while (i < lines.length && /^>\s?/.test(lines[i])) {
        body.push(lines[i].replace(/^>\s?/, ""));
        i++;
      }
      out.push(`<blockquote class="border-l-2 border-brand-500/50 pl-4 text-slate-400">${renderInline(body.join(" "))}</blockquote>`);
      continue;
    }

    // Unordered list.
    if (/^\s*[-*+]\s+/.test(line)) {
      const items: string[] = [];
      while (i < lines.length && /^\s*[-*+]\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*[-*+]\s+/, ""));
        i++;
      }
      flushList(items, false);
      continue;
    }

    // Ordered list.
    if (/^\s*\d+\.\s+/.test(line)) {
      const items: string[] = [];
      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*\d+\.\s+/, ""));
        i++;
      }
      flushList(items, true);
      continue;
    }

    // Paragraph: gather consecutive non-blank, non-structural lines.
    const para: string[] = [];
    while (
      i < lines.length &&
      lines[i].trim() !== "" &&
      !/^```/.test(lines[i]) &&
      !/^(#{1,6})\s/.test(lines[i]) &&
      !/^>\s?/.test(lines[i]) &&
      !/^\s*[-*+]\s+/.test(lines[i]) &&
      !/^\s*\d+\.\s+/.test(lines[i]) &&
      !/^(-{3,}|\*{3,}|_{3,})$/.test(lines[i].trim())
    ) {
      para.push(lines[i]);
      i++;
    }
    out.push(`<p class="leading-relaxed text-slate-300">${renderInline(para.join(" "))}</p>`);
  }

  return out.join("\n");
}

"use client";

import { useMemo, useState } from "react";

export type DocSection = {
  id: string;
  title: string;
  /** Pre-rendered, sanitized HTML for this section. */
  html: string;
  /** Lowercased plain text, for the client-side filter. */
  search: string;
};

/**
 * Renders the pre-sanitized documentation sections with a client-side filter
 * box. The markdown is rendered to safe HTML on the server (see lib/markdown.ts)
 * — this component only shows/hides sections, it never re-parses source.
 */
export function DocsViewer({ sections }: { sections: DocSection[] }) {
  const [q, setQ] = useState("");
  const query = q.trim().toLowerCase();

  const visible = useMemo(
    () => (query ? sections.filter((s) => s.search.includes(query)) : sections),
    [sections, query]
  );

  return (
    <div className="space-y-6">
      <div className="sticky top-16 z-10 -mx-1 bg-navy-950/80 px-1 py-2 backdrop-blur">
        <input
          className="input w-full py-2.5"
          type="search"
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder="Search the documentation…"
        />
        {query && (
          <p className="mt-2 text-xs text-slate-500">
            {visible.length} section{visible.length === 1 ? "" : "s"} match “{q}”.
          </p>
        )}
      </div>

      {visible.length === 0 ? (
        <div className="card py-12 text-center text-sm text-slate-400">
          No documentation sections match “{q}”.
        </div>
      ) : (
        <div className="card space-y-3 p-6">
          {visible.map((s) => (
            <section
              key={s.id}
              className="prose-invert space-y-3 [&_h2]:scroll-mt-24"
              dangerouslySetInnerHTML={{ __html: s.html }}
            />
          ))}
        </div>
      )}
    </div>
  );
}

import { promises as fs } from "fs";
import path from "path";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge } from "@/components/ui/primitives";
import { renderMarkdown } from "@/lib/markdown";
import { DocsViewer, type DocSection } from "@/components/admin/DocsViewer";

export const dynamic = "force-dynamic";

/**
 * Private, admin-only view of the platform documentation. Reads
 * docs/DOCUMENTATION.md straight off disk (server-side) and renders it with a
 * small in-house safe Markdown renderer — the public /docs page is retired.
 */
export default async function AdminDocs() {
  await requireArea("platform");

  let raw = "";
  let error: string | null = null;
  try {
    raw = await fs.readFile(path.join(process.cwd(), "docs", "DOCUMENTATION.md"), "utf8");
  } catch {
    error = "docs/DOCUMENTATION.md could not be read from disk.";
  }

  // Split into searchable sections at each H2 heading; everything before the
  // first H2 is the intro section.
  const sections: DocSection[] = [];
  if (raw) {
    const lines = raw.replace(/\r\n/g, "\n").split("\n");
    let title = "Overview";
    let buf: string[] = [];
    let idx = 0;
    const push = () => {
      const body = buf.join("\n").trim();
      if (!body && sections.length > 0) return;
      sections.push({
        id: `sec-${idx++}`,
        title,
        html: renderMarkdown(body),
        search: `${title}\n${body}`.toLowerCase(),
      });
    };
    for (const line of lines) {
      const h2 = line.match(/^##\s+(.*)$/);
      if (h2) {
        push();
        buf = [line];
        title = h2[1].trim();
      } else {
        buf.push(line);
      }
    }
    push();
  }

  return (
    <div className="space-y-6">
      <PageHeader title="Documentation" sub="Internal platform documentation — private to staff.">
        <Badge tone="brand">{sections.length} sections</Badge>
      </PageHeader>

      {error ? (
        <div className="card py-12 text-center text-sm text-red-300">{error}</div>
      ) : (
        <DocsViewer sections={sections} />
      )}
    </div>
  );
}

"use server";

import { revalidatePath } from "next/cache";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";

/**
 * Owner-facing approve/decline actions for the Improvements board
 * (app/admin/improvements). Every action is ADMIN-guarded via requireAdmin(),
 * mirroring the other admin action modules.
 */

export const IMPROVEMENT_STATUSES = [
  "PROPOSED",
  "APPROVED",
  "DECLINED",
  "IN_PROGRESS",
  "DONE",
] as const;

export type ImprovementStatus = (typeof IMPROVEMENT_STATUSES)[number];

function assertStatus(status: string): asserts status is ImprovementStatus {
  if (!(IMPROVEMENT_STATUSES as readonly string[]).includes(status)) {
    throw new Error(`Invalid improvement status: ${status}`);
  }
}

async function audit(userId: string | null, action: string, detail?: string) {
  try {
    await db.auditLog.create({ data: { userId, action, detail } });
  } catch {
    /* auditing is best-effort — never block the status change on it */
  }
}

/** Set a single improvement's status. */
export async function setImprovementStatus(id: string, status: string): Promise<void> {
  const admin = await requireAdmin();
  assertStatus(status);
  await db.improvement.update({ where: { id }, data: { status } });
  await audit(admin.id, "improvement.status", `${id} → ${status}`);
  revalidatePath("/admin/improvements");
}

/** Selector for a bulk status change: an explicit id list and/or a filter. */
export type BulkImprovementSelector = {
  /** Explicit row ids. */
  ids?: string[];
  /** Restrict to a category (e.g. "bug"). */
  category?: string;
  /** Only touch rows currently in this status (e.g. only PROPOSED). */
  onlyStatus?: string;
};

/**
 * Bulk status change. Accepts either an explicit id list, a filter (category /
 * current status), or both. With no constraints at all it is a no-op guard —
 * we refuse an unbounded update so "Approve all" can never sweep the whole
 * table by accident.
 */
export async function bulkSetStatus(
  selector: BulkImprovementSelector,
  status: string
): Promise<{ count: number }> {
  const admin = await requireAdmin();
  assertStatus(status);

  const where: {
    id?: { in: string[] };
    category?: string;
    status?: string;
  } = {};
  if (selector.ids && selector.ids.length > 0) where.id = { in: selector.ids };
  if (selector.category) where.category = selector.category;
  if (selector.onlyStatus) {
    assertStatus(selector.onlyStatus);
    where.status = selector.onlyStatus;
  }

  // Refuse a truly unconstrained bulk update.
  if (Object.keys(where).length === 0) return { count: 0 };

  const res = await db.improvement.updateMany({ where, data: { status } });
  await audit(
    admin.id,
    "improvement.bulkStatus",
    `${res.count} row(s) → ${status} (${JSON.stringify(selector)})`
  );
  revalidatePath("/admin/improvements");
  return { count: res.count };
}

"use client";

import { useMemo, useState, useTransition } from "react";
import { Badge } from "@/components/ui/primitives";
import {
  setImprovementStatus,
  bulkSetStatus,
  type ImprovementStatus,
} from "@/lib/actions-improvements";

export type BoardItem = {
  id: string;
  category: string;
  severity: string;
  title: string;
  summary: string;
  detail: string | null;
  source: string | null;
  effort: string | null;
  filesHint: string | null;
  status: string;
  createdAt: string;
};

const STATUS_TABS: { key: ImprovementStatus | "ALL"; label: string }[] = [
  { key: "PROPOSED", label: "Proposed" },
  { key: "APPROVED", label: "Approved" },
  { key: "IN_PROGRESS", label: "In progress" },
  { key: "DECLINED", label: "Declined" },
  { key: "DONE", label: "Done" },
  { key: "ALL", label: "All" },
];

const SEVERITY_ORDER: Record<string, number> = { critical: 0, high: 1, medium: 2, low: 3 };

function severityTone(sev: string): "red" | "amber" | "brand" | "slate" {
  if (sev === "critical") return "red";
  if (sev === "high") return "amber";
  if (sev === "medium") return "brand";
  return "slate";
}

function cap(s: string): string {
  return s ? s.charAt(0).toUpperCase() + s.slice(1) : s;
}

function Card({
  item,
  pending,
  onSet,
}: {
  item: BoardItem;
  pending: boolean;
  onSet: (id: string, status: ImprovementStatus) => void;
}) {
  const [open, setOpen] = useState(false);
  return (
    <div className="card p-4">
      <div className="flex items-start gap-3">
        <Badge tone={severityTone(item.severity)}>{item.severity}</Badge>
        <div className="min-w-0 flex-1">
          <p className="text-sm text-slate-300">
            <span className="font-semibold text-white">{item.title}</span>
            {" — "}
            {item.summary}
          </p>
          <div className="mt-2 flex flex-wrap items-center gap-2 text-[11px] text-slate-500">
            {item.effort && <Badge tone="slate">effort {item.effort}</Badge>}
            {item.source && <span>via {item.source}</span>}
            <span>· {new Date(item.createdAt).toLocaleDateString()}</span>
            {item.detail && (
              <button
                className="text-brand-300 hover:text-brand-200"
                onClick={() => setOpen((v) => !v)}
              >
                {open ? "Hide detail" : "Show detail"}
              </button>
            )}
          </div>
          {open && item.detail && (
            <div className="mt-3 space-y-2 rounded-lg border border-white/[0.06] bg-navy-950/50 p-3 text-[13px] leading-relaxed text-slate-300">
              <p className="whitespace-pre-wrap">{item.detail}</p>
              {item.filesHint && (
                <p className="text-xs text-slate-500">
                  Files: <span className="font-mono text-slate-400">{item.filesHint}</span>
                </p>
              )}
            </div>
          )}
        </div>
        <div className="flex shrink-0 flex-col items-end gap-1.5">
          {item.status !== "PROPOSED" && <Badge tone="slate">{item.status.toLowerCase().replace(/_/g, " ")}</Badge>}
          <div className="flex gap-1.5">
            {item.status !== "APPROVED" && (
              <button
                disabled={pending}
                onClick={() => onSet(item.id, "APPROVED")}
                className="rounded-lg border border-emerald-500/40 bg-emerald-500/10 px-2.5 py-1 text-xs font-semibold text-emerald-300 transition-colors hover:bg-emerald-500/20 disabled:opacity-50"
              >
                Approve
              </button>
            )}
            {item.status !== "DECLINED" && (
              <button
                disabled={pending}
                onClick={() => onSet(item.id, "DECLINED")}
                className="rounded-lg border border-red-500/40 bg-red-500/10 px-2.5 py-1 text-xs font-semibold text-red-300 transition-colors hover:bg-red-500/20 disabled:opacity-50"
              >
                Decline
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export function ImprovementsBoard({ items }: { items: BoardItem[] }) {
  const [tab, setTab] = useState<ImprovementStatus | "ALL">("PROPOSED");
  const [pending, startTransition] = useTransition();

  const statusCounts = useMemo(() => {
    const c: Record<string, number> = {};
    for (const it of items) c[it.status] = (c[it.status] ?? 0) + 1;
    return c;
  }, [items]);

  const filtered = useMemo(
    () => (tab === "ALL" ? items : items.filter((it) => it.status === tab)),
    [items, tab]
  );

  // Group by category, each group's cards sorted by severity (critical → low).
  const groups = useMemo(() => {
    const map = new Map<string, BoardItem[]>();
    for (const it of filtered) {
      const arr = map.get(it.category) ?? [];
      arr.push(it);
      map.set(it.category, arr);
    }
    return [...map.entries()]
      .map(([category, rows]) => ({
        category,
        rows: rows.sort(
          (a, b) => (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9)
        ),
      }))
      .sort((a, b) => a.category.localeCompare(b.category));
  }, [filtered]);

  const set = (id: string, status: ImprovementStatus) =>
    startTransition(() => setImprovementStatus(id, status));

  const approveGroup = (category: string) =>
    startTransition(() =>
      bulkSetStatus({ category, onlyStatus: "PROPOSED" }, "APPROVED").then(() => undefined)
    );

  const approveAll = () =>
    startTransition(() =>
      bulkSetStatus({ onlyStatus: "PROPOSED" }, "APPROVED").then(() => undefined)
    );

  const proposedShown = filtered.some((it) => it.status === "PROPOSED");

  return (
    <div className="space-y-6">
      {/* Status filter tabs */}
      <div className="flex flex-wrap items-center gap-1.5 border-b border-white/[0.06] pb-3">
        {STATUS_TABS.map((t) => {
          const n = t.key === "ALL" ? items.length : statusCounts[t.key] ?? 0;
          const active = tab === t.key;
          return (
            <button
              key={t.key}
              onClick={() => setTab(t.key)}
              className={`rounded-full px-3.5 py-1.5 text-[13px] font-medium transition-colors ${
                active
                  ? "bg-brand-500/15 text-brand-200 ring-1 ring-inset ring-brand-500/40"
                  : "text-slate-400 hover:bg-white/[0.05] hover:text-slate-200"
              }`}
            >
              {t.label}
              <span className="ml-1.5 text-slate-500">{n}</span>
            </button>
          );
        })}
        {tab === "PROPOSED" && proposedShown && (
          <button
            disabled={pending}
            onClick={approveAll}
            className="ml-auto rounded-lg border border-emerald-500/40 bg-emerald-500/10 px-3 py-1.5 text-xs font-semibold text-emerald-300 transition-colors hover:bg-emerald-500/20 disabled:opacity-50"
          >
            Approve all proposed
          </button>
        )}
      </div>

      {/* Per-category count chips for the active filter */}
      {groups.length > 0 && (
        <div className="flex flex-wrap gap-2">
          {groups.map((g) => (
            <span
              key={g.category}
              className="inline-flex items-center gap-1.5 rounded-full border border-white/10 bg-white/[0.04] px-3 py-1 text-xs text-slate-300"
            >
              {cap(g.category)}
              <span className="font-semibold text-white">{g.rows.length}</span>
            </span>
          ))}
        </div>
      )}

      {groups.length === 0 ? (
        <div className="card py-12 text-center text-sm text-slate-400">
          Nothing here — no improvements with this status.
        </div>
      ) : (
        groups.map((g) => (
          <section key={g.category} className="space-y-3">
            <div className="flex items-center justify-between">
              <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-400">
                {cap(g.category)}
                <span className="ml-2 text-slate-600">{g.rows.length}</span>
              </h2>
              {tab === "PROPOSED" && g.rows.some((r) => r.status === "PROPOSED") && (
                <button
                  disabled={pending}
                  onClick={() => approveGroup(g.category)}
                  className="rounded-lg border border-emerald-500/30 bg-emerald-500/5 px-2.5 py-1 text-xs font-medium text-emerald-300 transition-colors hover:bg-emerald-500/15 disabled:opacity-50"
                >
                  Approve all {cap(g.category)}
                </button>
              )}
            </div>
            <div className="space-y-2.5">
              {g.rows.map((it) => (
                <Card key={it.id} item={it} pending={pending} onSet={set} />
              ))}
            </div>
          </section>
        ))
      )}
    </div>
  );
}

import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader, Badge } from "@/components/ui/primitives";
import { ImprovementsBoard, type BoardItem } from "@/components/admin/ImprovementsBoard";

export const dynamic = "force-dynamic";

/**
 * Owner-facing Improvements board. Nightly scans (scripts/write-improvement.ts)
 * INSERT proposals here; the owner triages them with per-card and bulk
 * approve/decline. Grouped by category and sorted by severity so the summary is
 * skimmable without reading every detail.
 */
export default async function AdminImprovements() {
  await requireArea("platform");

  const rows = await db.improvement.findMany({
    orderBy: [{ createdAt: "desc" }],
    take: 500,
  });

  const items: BoardItem[] = rows.map((r) => ({
    id: r.id,
    category: r.category,
    severity: r.severity,
    title: r.title,
    summary: r.summary,
    detail: r.detail,
    source: r.source,
    effort: r.effort,
    filesHint: r.filesHint,
    status: r.status,
    createdAt: r.createdAt.toISOString(),
  }));

  const proposed = items.filter((i) => i.status === "PROPOSED").length;

  return (
    <div className="space-y-6">
      <PageHeader
        title="Improvements"
        sub="Proposals from the nightly scan and other signals — approve or decline to steer the roadmap."
      >
        {proposed > 0 ? (
          <Badge tone="amber">{proposed} awaiting review</Badge>
        ) : (
          <Badge tone="green">all triaged</Badge>
        )}
      </PageHeader>

      <ImprovementsBoard items={items} />
    </div>
  );
}

/**
 * Insert one Improvement proposal into the board (app/admin/improvements).
 *
 * Meant to be called by the nightly scan, one invocation per finding:
 *
 *   npx tsx scripts/write-improvement.ts \
 *     --category bug --severity high \
 *     --title "Race in provisioning worker" \
 *     --summary "Two jobs can grab the same IP under load." \
 *     [--detail "..."] [--batchId 2026-07-24] [--source nightly-scan] \
 *     [--effort M] [--filesHint "lib/provisioner.ts"]
 *
 * The runner is CJS, so there is NO top-level await — everything runs inside
 * main().
 */

import { db } from "../lib/db";

/** Parse --key value / --key=value flags into a map. */
function parseArgs(argv: string[]): Record<string, string> {
  const out: Record<string, string> = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (!a.startsWith("--")) continue;
    const key = a.slice(2);
    const eq = key.indexOf("=");
    if (eq >= 0) {
      out[key.slice(0, eq)] = key.slice(eq + 1);
    } else {
      const next = argv[i + 1];
      if (next && !next.startsWith("--")) {
        out[key] = next;
        i++;
      } else {
        out[key] = "true";
      }
    }
  }
  return out;
}

const CATEGORIES = ["bug", "feature", "error", "enhancement", "security", "performance"];
const SEVERITIES = ["low", "medium", "high", "critical"];
const EFFORTS = ["S", "M", "L"];

async function main() {
  const args = parseArgs(process.argv.slice(2));

  const category = (args.category ?? "").toLowerCase().trim();
  const severity = (args.severity ?? "medium").toLowerCase().trim();
  const title = (args.title ?? "").trim();
  const summary = (args.summary ?? "").trim();

  const missing: string[] = [];
  if (!category) missing.push("--category");
  if (!title) missing.push("--title");
  if (!summary) missing.push("--summary");
  if (missing.length) {
    console.error(`write-improvement: missing required flag(s): ${missing.join(", ")}`);
    process.exit(1);
  }
  if (!CATEGORIES.includes(category)) {
    console.error(`write-improvement: --category must be one of ${CATEGORIES.join(" | ")}`);
    process.exit(1);
  }
  if (!SEVERITIES.includes(severity)) {
    console.error(`write-improvement: --severity must be one of ${SEVERITIES.join(" | ")}`);
    process.exit(1);
  }

  const effort = args.effort ? args.effort.toUpperCase().trim() : null;
  if (effort && !EFFORTS.includes(effort)) {
    console.error(`write-improvement: --effort must be one of ${EFFORTS.join(" | ")}`);
    process.exit(1);
  }

  const row = await db.improvement.create({
    data: {
      category,
      severity,
      title,
      summary,
      detail: args.detail ?? null,
      batchId: args.batchId ?? null,
      source: args.source ?? "nightly-scan",
      effort,
      filesHint: args.filesHint ?? null,
      status: "PROPOSED",
    },
  });

  console.log(`Improvement created: ${row.id} [${row.category}/${row.severity}] ${row.title}`);
  await db.$disconnect();
}

main().catch(async (e) => {
  console.error(e);
  try {
    await db.$disconnect();
  } catch {
    /* ignore */
  }
  process.exit(1);
});

